package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseP2MigrationTest extends MigrationTestSupport {
 @Test void populatedLegacyBookingSurvivesRollbackAndRetryWithoutInventingFinancialEvidence(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_p2_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("73").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID a=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('p2-legacy-a@example.test','synthetic','ACTIVE') RETURNING id",UUID.class),b=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('p2-legacy-b@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);db.update("INSERT INTO professional_profiles(user_id,professional_type,title,verification_status) VALUES(?,'COUNSELOR','Legacy professional','PENDING')",b);UUID id=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,scheduled_at,consultation_mode,status,note) VALUES(?,?,CURRENT_TIMESTAMP,'TEXT','COMPLETED','Legacy private request, no verified clinical completion') RETURNING id",UUID.class,a,b);var original=db.queryForMap("SELECT status,note,scheduled_at FROM consultation_requests WHERE id=?",id);db.execute("CREATE TABLE clinic_invoices(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.columns WHERE table_schema=? AND table_name='consultation_requests' AND column_name='clinic_governed'",Integer.class,schema)).isZero();db.execute("DROP TABLE clinic_invoices");Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate();assertThat(db.queryForMap("SELECT status,note,scheduled_at FROM consultation_requests WHERE id=?",id)).isEqualTo(original);assertThat(db.queryForObject("SELECT clinic_governed FROM consultation_requests WHERE id=?",Boolean.class,id)).isFalse();assertThat(db.queryForObject("SELECT count(*) FROM clinic_financial_events",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM clinic_subscription_plans",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
